//! New OS kernel — milestone 1 bootable prototype plus the milestone-2 memory and exception work.
//!
//! # Boot flow (see `docs/architecture/adr/ADR-0003-boot-path.md`)
//!
//! 1. QEMU firmware: SeaBIOS for the BIOS image, OVMF for the UEFI image.
//! 2. The `bootloader` 0.11 crate (reused component) loads this kernel's ELF from the FAT
//!    partition of the generated disk image, creates the kernel's page tables and stack, and
//!    jumps to `_start`.
//! 3. `_start`, generated by `bootloader_api::entry_point!`, calls [`kernel_main`] with
//!    `&'static mut BootInfo`.
//!
//! # What this code actually does
//!
//! Opens the COM1 serial console, installs our own exception tables (GDT, TSS with a double-fault
//! IST stack, and a 256-entry IDT; see [`interrupts`]) and proves them with a real breakpoint trap
//! and a real, resumed page fault, then starts the PIT timer and proves it delivers IRQ0 interrupts,
//! then reports a summary of what the bootloader handed over, validates the reported memory map with
//! checked arithmetic (see [`report_memory_map`]), builds a bitmap physical frame allocator over
//! validated usable regions, takes a small bootstrap allocation from it, builds the kernel's **own**
//! top-level page table (a private PML4 mirroring the bootloader's entries plus one new mapping from
//! its own frames) and installs it by loading `CR3` (see [`paging::install_own_page_tables`]), prints
//! `NEW_OS_KERNEL_MEMORY_OK`, prints `NEW_OS_KERNEL_BOOT_OK`, then halts the CPU.
//!
//! # What this code does NOT do
//!
//! The kernel owns only the **top level** of its page tables: the lower levels behind the mirrored
//! entries are still the `bootloader` component's, so nothing here maps an arbitrary range, unmaps,
//! reclaims frames or applies per-page protection (every mapping stays writable and user-accessible
//! as the bootloader left it). Interrupts exist, but only
//! the legacy PIC/PIT timer is enabled and nothing consumes its ticks: there is **no scheduler**, no
//! task or process model, and every other interrupt line stays masked. No userspace or syscalls, no
//! drivers beyond the debug UART, no filesystem, no graphics output, no desktop and no Windows
//! compatibility. The bootstrap frames handed out by [`allocate_bootstrap_frames`] are taken but not
//! yet used for anything.
//! See `docs/roadmap/MILESTONES.md` for the milestones that own those features.

#![no_std]
#![no_main]

mod interrupts;
mod paging;

use bootloader_api::info::{MemoryRegionKind, MemoryRegions};
use bootloader_api::{BootInfo, entry_point};
use core::cell::UnsafeCell;
use core::fmt::{self, Write};
use core::panic::PanicInfo;
use physmem::{FrameAllocator, MapSummary, MapValidator, MemoryRegion, RegionKind};
use uart16550::{SerialPort, TxOutcome};

/// Bootloader configuration handed to the `bootloader` component through the `.bootloader-config`
/// section.
///
/// The kernel needs to read paging-structure entries to translate the virtual addresses `BootInfo`
/// reports (see [`paging`]), so it asks the bootloader to map all physical memory at a dynamic
/// virtual offset. Without this, `BootInfo::physical_memory_offset` is `None` and translation is
/// impossible — which is exactly what the first attempt at this slice found.
pub static BOOTLOADER_CONFIG: bootloader_api::BootloaderConfig = {
    let mut config = bootloader_api::BootloaderConfig::new_default();
    config.mappings.physical_memory = Some(bootloader_api::config::Mapping::Dynamic);
    config
};

entry_point!(kernel_main, config = &BOOTLOADER_CONFIG);

/// I/O port base of the first legacy serial port (COM1). QEMU's `-serial` option is attached to
/// this port, which is why the smoke test reads the guest log from there.
const COM1_BASE: u16 = 0x03F8;

/// Baud rate the serial console is programmed to.
const SERIAL_BAUD: u32 = 115_200;

/// Printed once the serial console, the boot handoff report and the memory path have all succeeded.
///
/// `tools/test/qemu-smoke.sh` and the CI boot job assert on this exact string, and it must originate
/// from this kernel's own serial writes for the test to mean anything.
const BOOT_SUCCESS_MARKER: &str = "NEW_OS_KERNEL_BOOT_OK";

/// Printed after the memory map has been validated and the frame allocator has been built and used.
///
/// Also asserted by `tools/test/qemu-smoke.sh`, so the milestone-2 memory path cannot silently stop
/// running without a test failing.
const MEMORY_SUCCESS_MARKER: &str = "NEW_OS_KERNEL_MEMORY_OK";

/// Printed after the exception tables are installed and both exception self-tests have passed.
///
/// Also asserted by `tools/test/qemu-smoke.sh`. The marker is emitted only after a real breakpoint
/// trap and a real page fault have been reported and resumed, so it cannot be printed by a kernel
/// that merely loaded an IDT.
const EXCEPTION_SUCCESS_MARKER: &str = "NEW_OS_KERNEL_EXCEPTION_OK";

/// Printed after the PIT timer has been started and has been observed to interrupt the CPU.
///
/// Also asserted by `tools/test/qemu-smoke.sh`. The marker is emitted only after a minimum number of
/// real IRQ0 interrupts have landed in the handler, so it cannot be printed by a kernel that merely
/// programmed the PIT without unmasking or enabling interrupts.
const TIMER_SUCCESS_MARKER: &str = "NEW_OS_KERNEL_TIMER_OK";

/// Timer interrupts the boot self-test waits for before declaring the timer working.
const TIMER_SELF_TEST_TICKS: u64 = 3;

/// Printed once the kernel has translated the virtual addresses `BootInfo` reports for its stack and
/// the framebuffer with its own page-table walk, and reserved their physical frames.
///
/// Also asserted by `tools/test/qemu-smoke.sh`, so the translation cannot silently stop working.
const PAGING_SUCCESS_MARKER: &str = "NEW_OS_KERNEL_PAGING_OK";

/// Printed once the kernel has built a top-level page table of its own, added a mapping to it from
/// freshly allocated frames, and installed it by loading `CR3`.
///
/// Also asserted by `tools/test/qemu-smoke.sh`, so the kernel cannot silently fall back to running
/// on the bootloader's table.
const PAGE_TABLES_SUCCESS_MARKER: &str = "NEW_OS_KERNEL_PAGETABLES_OK";

/// Physical address space the frame bitmap describes: the first 4 GiB.
///
/// Usable memory above this limit is out of reach of this bootstrap allocator. That is not silent:
/// [`report_frame_allocator`] prints how many whole frames were ignored, and the limit is recorded
/// in `docs/architecture/adr/ADR-0014-boot-memory-handling.md`.
const MANAGED_PHYSICAL_BYTES: u64 = 4 * 1024 * 1024 * 1024;

/// Frame size shift: 2^12 = 4 KiB, the x86-64 base page size.
const FRAME_SHIFT: u32 = 12;

/// Words in the frame bitmap: one bit per 4 KiB frame of [`MANAGED_PHYSICAL_BYTES`] (128 KiB).
const FRAME_BITMAP_WORDS: usize = (MANAGED_PHYSICAL_BYTES / (1 << FRAME_SHIFT) / 64) as usize;

/// Physical memory at the bottom of the address space that is never handed out.
///
/// Firmware reports most of the first MiB as usable, but it contains real-mode structures the
/// firmware and BIOS interrupt handlers still use: the interrupt vector table and BIOS data area at
/// the bottom, and the extended BIOS data area above it, which can move between boots. Reserving the
/// whole MiB is the simple, safe policy; the cost is 0.4% of the memory in the smallest supported
/// guest (256 MiB). The policy and its reasoning are recorded in
/// `docs/architecture/adr/ADR-0014-boot-memory-handling.md`.
const LOW_MEMORY_RESERVED_BYTES: u64 = 1024 * 1024;

/// Bootstrap frames taken from the allocator just after it is built.
///
/// Reserved for the follow-up milestone-2 work (our own page tables and fault stacks). Nothing maps
/// them yet, and this is deliberately reported rather than silently held.
const BOOTSTRAP_FRAMES: u64 = 8;

/// Bytes in one MiB, used only for display.
const BYTES_PER_MIB: u64 = 1024 * 1024;

/// `.bss` storage for the frame bitmap.
///
/// `UnsafeCell` plus a hand-written `Sync` implementation is how mutable kernel state lives in a
/// `static` before any locking primitive exists.
struct FrameBitmapStorage(UnsafeCell<[u64; FRAME_BITMAP_WORDS]>);

// SAFETY: this milestone has a single CPU, runs with interrupts disabled, has no scheduler and no
// other agent that could touch the bitmap, so there is no way for two executions to hold a mutable
// reference to it at once. Every access goes through `frame_bitmap()`, which is called only from
// `kernel_main` on that single path. Introducing interrupts, SMP or an allocator API reachable from
// more than one context requires replacing this with a properly synchronised structure first.
unsafe impl Sync for FrameBitmapStorage {}

/// The kernel's frame bitmap, zero-initialised by the loader's `.bss` handling.
static FRAME_BITMAP: FrameBitmapStorage =
    FrameBitmapStorage(UnsafeCell::new([0; FRAME_BITMAP_WORDS]));

/// Writes one line of diagnostics to a serial console, ignoring transmit failures.
///
/// Logging never panics or blocks: [`SerialPort::write_byte`] bounds its own polling, so a missing
/// or faulty UART degrades to dropped bytes. Callers that need transmit assurance (the boot
/// markers) use [`write_marker`].
pub(crate) fn write_line(console: &mut SerialPort, args: fmt::Arguments<'_>) {
    let _ = Write::write_fmt(console, args);
    let _ = Write::write_char(console, '\n');
}

/// Reports a fatal condition on the serial console and parks the CPU.
///
/// Used for failures with no recovery path. Saying what went wrong before halting is the whole point
/// of the boot prototype: an unexplained hang is not an acceptable failure mode.
fn fatal(console: &mut SerialPort, args: fmt::Arguments<'_>) -> ! {
    write_line(console, format_args!("[FATAL] {args}"));
    halt_forever()
}

/// The kernel's frame bitmap as a mutable slice.
///
/// # Safety
///
/// The caller must be the only execution context able to reach the bitmap; see the `Sync`
/// implementation on [`FrameBitmapStorage`]. It must also be called at most once at a time, so the
/// returned reference cannot be aliased by a second live reference.
unsafe fn frame_bitmap() -> &'static mut [u64] {
    // SAFETY: the storage is a `static` with no other owner, the cast preserves the array length,
    // and the single-threaded, interrupt-free caller contract above rules out aliasing.
    unsafe { &mut *FRAME_BITMAP.0.get() }
}

/// Kernel entry point registered by the `entry_point!` macro above.
fn kernel_main(boot_info: &'static mut BootInfo) -> ! {
    let mut console = open_serial_console();

    write_line(
        &mut console,
        format_args!("new-os kernel: milestone 2 prototype (x86-64, no_std)"),
    );
    write_line(
        &mut console,
        format_args!("boot path: firmware -> bootloader 0.11 -> _start -> kernel_main"),
    );

    // Install our own exception tables before anything that can fault (the memory-map walk and the
    // frame allocator both touch untrusted data), then prove the path works end to end.
    interrupts::init();
    write_line(
        &mut console,
        format_args!("exceptions: GDT, TSS (IST for #DF) and 256-entry IDT installed"),
    );
    match interrupts::run_self_tests() {
        Ok(()) => write_marker(&mut console, EXCEPTION_SUCCESS_MARKER),
        Err(reason) => fatal(
            &mut console,
            format_args!("exception self-test failed: {reason}"),
        ),
    }

    // Start the hardware timer and prove it delivers interrupts before continuing. The timer keeps
    // running for the rest of the boot; nothing consumes the ticks yet because there is no scheduler.
    interrupts::enable_timer();
    interrupts::wait_for_ticks(TIMER_SELF_TEST_TICKS);
    write_marker(&mut console, TIMER_SUCCESS_MARKER);
    write_line(
        &mut console,
        format_args!(
            "timer: PIT at {} Hz; {} interrupt(s) observed (IRQ0 -> vector 32)",
            interrupts::TIMER_HZ,
            interrupts::timer_ticks()
        ),
    );

    report_boot_handoff(&mut console, boot_info);

    let Some(summary) = report_memory_map(&mut console, &boot_info.memory_regions) else {
        halt_forever()
    };
    let Some((mut allocator, totals)) = build_frame_allocator(&mut console, boot_info) else {
        halt_forever()
    };
    report_frame_allocator(&mut console, &summary, &allocator, &totals);
    allocate_bootstrap_frames(&mut console, &mut allocator);

    // Build our own page tables and run on them. A failure here leaves the kernel running on the
    // bootloader's table, so it is reported but not fatal; the smoke test still fails, because the
    // marker below is only emitted on success.
    match paging::install_own_page_tables(&mut console, &mut allocator, boot_info) {
        Ok(()) => write_marker(&mut console, PAGE_TABLES_SUCCESS_MARKER),
        Err(reason) => write_line(
            &mut console,
            format_args!(
                "[FAILURE] could not install the kernel's own page tables: {reason}; still running on the bootloader's tables"
            ),
        ),
    }

    write_marker(&mut console, MEMORY_SUCCESS_MARKER);
    write_marker(&mut console, BOOT_SUCCESS_MARKER);
    write_line(
        &mut console,
        format_args!("initialisation path complete; halting (no scheduler in milestone 2)"),
    );

    halt_forever()
}

/// Opens the COM1 serial console used for all diagnostics in this milestone.
///
/// Halts silently if the UART cannot be programmed. At this point in boot there is no other
/// console to report on, and [`COM1_BASE`]/[`SERIAL_BAUD`] are constants whose divisor is known to
/// be representable, so this path only triggers if the port I/O mechanism itself is broken.
fn open_serial_console() -> SerialPort {
    // SAFETY: this is the earliest kernel code to run. The bootloader has handed control over to
    // us and exited, the CPU is at ring 0, and no other driver, task or firmware agent exists
    // yet, so the kernel is the sole owner of the COM1 UART.
    let console = unsafe { SerialPort::new(COM1_BASE) };
    if !console.init(SERIAL_BAUD) {
        halt_forever()
    }
    console
}

/// Reports a truthful summary of the bootloader handoff.
///
/// This only states what the bootloader's `BootInfo` says; the memory map is validated separately
/// by [`report_memory_map`], and nothing here is trusted before that.
fn report_boot_handoff(console: &mut SerialPort, boot_info: &BootInfo) {
    write_line(console, format_args!("boot handoff:"));
    write_line(
        console,
        format_args!(
            "  kernel ELF: physical {:#018x}, {} bytes, mapped at virtual offset {:#x}",
            boot_info.kernel_addr, boot_info.kernel_len, boot_info.kernel_image_offset
        ),
    );
    write_line(
        console,
        format_args!(
            "  kernel stack: {} bytes at virtual {:#018x}",
            boot_info.kernel_stack_len, boot_info.kernel_stack_bottom
        ),
    );
    write_line(
        console,
        format_args!(
            "  physical memory regions reported: {}",
            boot_info.memory_regions.len()
        ),
    );

    match boot_info.framebuffer.as_ref() {
        Some(framebuffer) => {
            let info = framebuffer.info();
            write_line(
                console,
                format_args!(
                    "  framebuffer: {}x{}, stride {}, {} bytes/pixel, {:?}",
                    info.width, info.height, info.stride, info.bytes_per_pixel, info.pixel_format
                ),
            );
        }
        None => write_line(
            console,
            format_args!("  framebuffer: none reported by the bootloader"),
        ),
    }

    match boot_info.rsdp_addr.as_ref() {
        Some(addr) => write_line(console, format_args!("  ACPI RSDP address: {addr:#018x}")),
        None => write_line(console, format_args!("  ACPI RSDP address: not reported")),
    }

    match boot_info.physical_memory_offset.as_ref() {
        Some(offset) => write_line(
            console,
            format_args!("  physical memory offset: {offset:#018x}"),
        ),
        None => write_line(
            console,
            format_args!("  physical memory offset: not mapped (address translation unavailable)"),
        ),
    }
}

/// Translates a firmware region kind into the kernel's vocabulary.
///
/// Everything that is not reported as `Usable` is treated as reserved. In `bootloader_api` 0.11 the
/// non-usable kinds are `Bootloader` (memory the bootloader is still using, including the page
/// tables the kernel currently runs on), `UnknownUefi` and `UnknownBios` (raw firmware types the
/// bootloader did not classify). Deliberately not interpreted here: raw E820/UEFI type tags. The
/// bootloader has already translated them, and second-guessing that translation is not something
/// this milestone can validate.
fn region_kind(kind: MemoryRegionKind) -> RegionKind {
    match kind {
        MemoryRegionKind::Usable => RegionKind::Usable,
        _ => RegionKind::Reserved,
    }
}

/// Validates every region of the boot memory map and prints a summary.
///
/// Returns `None` if any region is defective; the caller must treat that as fatal, because a map
/// containing a defect cannot be trusted to describe real memory.
fn report_memory_map(console: &mut SerialPort, regions: &MemoryRegions) -> Option<MapSummary> {
    let mut validator = MapValidator::new();
    let mut defects = 0_usize;

    for (index, region) in regions.iter().enumerate() {
        let kind = region_kind(region.kind);
        let bounds = match MemoryRegion::from_bounds(region.start, region.end, kind) {
            Ok(bounds) => bounds,
            Err(err) => {
                write_line(
                    console,
                    format_args!("[FATAL] memory map: region #{index}: {err}"),
                );
                defects += 1;
                continue;
            }
        };
        if let Err(defect) = validator.add(bounds) {
            write_line(console, format_args!("[FATAL] memory map: {defect}"));
            defects += 1;
        }
    }

    if defects > 0 {
        write_line(
            console,
            format_args!(
                "[FATAL] {defects} of {} memory regions are unusable; refusing to manage physical memory from this map",
                regions.len()
            ),
        );
        return None;
    }

    let summary = validator.summary();
    write_line(
        console,
        format_args!("memory map: {} regions validated", validator.regions_seen()),
    );
    write_line(
        console,
        format_args!(
            "  usable: {} bytes ({} MiB), reserved: {} bytes, reclaimable: {} bytes",
            summary.usable_bytes,
            summary.usable_bytes / BYTES_PER_MIB,
            summary.reserved_bytes,
            summary.reclaimable_bytes
        ),
    );
    write_line(
        console,
        format_args!(
            "  highest reported address: {:#018x}{}",
            summary.highest_end,
            if summary.totals_saturated {
                " (byte totals saturated; they are lower bounds)"
            } else {
                ""
            }
        ),
    );
    Some(summary)
}

/// What building the allocator observed about the map, beyond the allocator's own state.
#[derive(Debug, Clone, Copy, Default)]
struct MarkingTotals {
    /// Whole frames the usable regions made free.
    frames_marked: u64,
    /// Whole frames inside usable regions that lie above the bitmap and are therefore not managed.
    out_of_range_frames: u64,
    /// Frames a usable region marked that a later non-usable region took back again. Non-zero means
    /// the map contains overlapping usable and non-usable regions.
    frames_reclaimed: u64,
}

/// Builds the frame allocator: usable regions first, then everything else, then the kernel's own
/// live memory.
///
/// Returns `None` (after reporting why) if any region is rejected by the allocator, which can only
/// happen if the map changed between validation and here or if the kernel's own reserved ranges are
/// malformed.
fn build_frame_allocator(
    console: &mut SerialPort,
    boot_info: &BootInfo,
) -> Option<(FrameAllocator<'static>, MarkingTotals)> {
    // SAFETY: `kernel_main` is the only caller, on a single CPU with interrupts disabled, and this
    // is the only place the bitmap reference is taken; see `FrameBitmapStorage`.
    let bitmap = unsafe { frame_bitmap() };
    let mut allocator = match FrameAllocator::new(bitmap, FRAME_SHIFT) {
        Ok(allocator) => allocator,
        Err(err) => fatal(console, format_args!("frame allocator unusable: {err}")),
    };
    let mut totals = MarkingTotals::default();

    // Pass 1: every usable region, so that usable claims are all in place before any claim that can
    // take memory away from them.
    for region in boot_info.memory_regions.iter() {
        if region_kind(region.kind) != RegionKind::Usable {
            continue;
        }
        let len = match region.end.checked_sub(region.start) {
            Some(len) => len,
            None => fatal(
                console,
                format_args!(
                    "usable region {:#018x}..{:#018x} ends before it starts",
                    region.start, region.end
                ),
            ),
        };
        match allocator.mark_usable(region.start, len) {
            Ok(report) => {
                totals.frames_marked += report.frames_marked;
                totals.out_of_range_frames += report.out_of_range_frames;
            }
            Err(err) => fatal(
                console,
                format_args!("usable region {:#018x} rejected: {err}", region.start),
            ),
        }
    }

    // Pass 2: everything else from the map (bootloader memory, firmware structures, MMIO holes).
    for region in boot_info.memory_regions.iter() {
        if region_kind(region.kind) == RegionKind::Usable {
            continue;
        }
        let len = match region.end.checked_sub(region.start) {
            Some(len) => len,
            None => fatal(
                console,
                format_args!(
                    "region {:#018x}..{:#018x} ends before it starts",
                    region.start, region.end
                ),
            ),
        };
        match allocator.mark_reserved(region.start, len) {
            Ok(report) => totals.frames_reclaimed += report.frames_cleared,
            Err(err) => fatal(
                console,
                format_args!("reserved region {:#018x} rejected: {err}", region.start),
            ),
        }
    }

    // Pass 3: the kernel's own live memory. The bootloader is expected to have marked these as
    // non-usable already, but a kernel that hands out the frames it is executing from is not worth
    // the risk, so they are reserved explicitly from the values in `BootInfo`.
    reserve_kernel_memory(console, &mut allocator, boot_info);

    Some((allocator, totals))
}

/// Reserves physical memory the kernel must not hand out, beyond what the map marks.
///
/// This covers the first MiB, the kernel image, and — new in this slice — the kernel stack and the
/// framebuffer, whose physical frames are now found by translating the virtual addresses `BootInfo`
/// reports through [`paging::translate`] instead of being assumed protected. A frame reservation
/// that the allocator rejects is reported but not fatal; see [`paging::reserve_translated`].
fn reserve_kernel_memory(
    console: &mut SerialPort,
    allocator: &mut FrameAllocator<'_>,
    boot_info: &BootInfo,
) {
    reserve_range(
        console,
        allocator,
        "first 1 MiB (real-mode firmware structures)",
        0,
        LOW_MEMORY_RESERVED_BYTES,
    );
    reserve_range(
        console,
        allocator,
        "kernel image",
        boot_info.kernel_addr,
        boot_info.kernel_len,
    );

    // The kernel stack and the framebuffer are reported only as virtual addresses. Translate them
    // through the page tables the bootloader installed and reserve their physical frames.
    let stack_reserved = paging::reserve_translated(
        console,
        allocator,
        boot_info,
        "kernel stack",
        boot_info.kernel_stack_bottom,
        boot_info.kernel_stack_len,
    );

    let framebuffer = boot_info.framebuffer.as_ref().map(|framebuffer| {
        let buffer = framebuffer.buffer();
        (buffer.as_ptr() as u64, buffer.len() as u64)
    });
    let framebuffer_reserved = match framebuffer {
        Some((start, len)) => {
            paging::reserve_translated(console, allocator, boot_info, "framebuffer", start, len)
        }
        None => {
            write_line(
                console,
                format_args!("  framebuffer: none reported, nothing to reserve"),
            );
            true
        }
    };

    if stack_reserved && framebuffer_reserved {
        write_marker(console, PAGING_SUCCESS_MARKER);
    }
}

/// Reserves one physical range and prints what was protected.
fn reserve_range(
    console: &mut SerialPort,
    allocator: &mut FrameAllocator<'_>,
    what: &str,
    start: u64,
    len: u64,
) {
    match allocator.mark_reserved(start, len) {
        Ok(report) => {
            write_line(
                console,
                format_args!(
                    "  reserved {what}: {start:#018x}..{end:#018x} ({len} bytes, {cleared} previously usable frame(s) reclaimed)",
                    end = start.saturating_add(len),
                    cleared = report.frames_cleared
                ),
            );
        }
        Err(err) => fatal(console, format_args!("failed to reserve {what}: {err}")),
    }
}

/// Prints the state of the allocator and the limits it ran into.
fn report_frame_allocator(
    console: &mut SerialPort,
    summary: &MapSummary,
    allocator: &FrameAllocator<'_>,
    totals: &MarkingTotals,
) {
    let frame_size = allocator.frame_size();
    write_line(
        console,
        format_args!(
            "frame allocator: {frame_size} byte frames; {} free of {} representable ({} MiB of RAM made available)",
            allocator.free_frames(),
            allocator.capacity_frames(),
            totals.frames_marked * frame_size / BYTES_PER_MIB
        ),
    );
    write_line(
        console,
        format_args!(
            "  marking: {} frames made usable, {} whole frame(s) above the {} MiB bitmap (not managed), {} reclaimed by non-usable regions",
            totals.frames_marked,
            totals.out_of_range_frames,
            MANAGED_PHYSICAL_BYTES / BYTES_PER_MIB,
            totals.frames_reclaimed
        ),
    );
    write_line(
        console,
        format_args!(
            "  firmware reported {} usable bytes ({} MiB); frames only partly inside a region are withheld",
            summary.usable_bytes,
            summary.usable_bytes / BYTES_PER_MIB
        ),
    );
}

/// Takes the bootstrap frames and prints the addresses, so the allocation is visible, not implied.
fn allocate_bootstrap_frames(console: &mut SerialPort, allocator: &mut FrameAllocator<'_>) {
    let mut first = None;
    let mut last = None;
    let mut taken = 0_u64;

    for _ in 0..BOOTSTRAP_FRAMES {
        match allocator.allocate() {
            Some(address) => {
                first.get_or_insert(address);
                last = Some(address);
                taken += 1;
            }
            None => break,
        }
    }

    if taken < BOOTSTRAP_FRAMES {
        fatal(
            console,
            format_args!(
                "bootstrap allocation obtained {taken} of {BOOTSTRAP_FRAMES} frames; the usable set is smaller than this prototype expects"
            ),
        )
    }

    write_line(
        console,
        format_args!(
            "bootstrap allocation: {taken} frames of {} bytes for the page-table work that follows",
            allocator.frame_size()
        ),
    );
    if let (Some(first), Some(last)) = (first, last) {
        write_line(
            console,
            format_args!(
                "  physical range {first:#018x}..{:#018x}; {} frame(s) now allocated, {} still free",
                last + allocator.frame_size(),
                allocator.allocated_frames(),
                allocator.free_frames()
            ),
        );
    }
}

/// Transmits a marker and verifies that the UART accepted every byte.
///
/// If any byte was dropped, the marker on the serial line may be truncated, so the boot is reported
/// as failed and the kernel halts instead of leaving a misleading (possibly partial) success line
/// behind. The smoke test asserts on these markers, so a truncated one must not be treated as a
/// pass by the kernel either.
fn write_marker(console: &mut SerialPort, marker: &str) {
    let mut dropped = 0_u32;
    for byte in marker.bytes().chain(*b"\n") {
        if console.write_byte(byte) == TxOutcome::Dropped {
            dropped += 1;
        }
    }
    if dropped > 0 {
        write_line(
            console,
            format_args!(
                "[FATAL] serial console dropped {dropped} byte(s); the boot marker cannot be trusted"
            ),
        );
        halt_forever()
    }
}

/// Required `#![no_std]` panic handler.
///
/// Diagnostic-first policy: attempt to report the panic on the serial console before halting so a
/// failed boot is observable instead of silent. If the UART was never initialised this is
/// best-effort, and the bounded polling in [`SerialPort`] means it degrades to dropped bytes
/// rather than hanging inside the panic handler.
#[panic_handler]
fn panic(info: &PanicInfo) -> ! {
    // SAFETY: same reasoning as `open_serial_console` — a single CPU at ring 0 with no other
    // agent using COM1. The panic handler cannot observe whether `open_serial_console` ran, and
    // writing to an uninitialised but present UART is harmless.
    let mut console = unsafe { SerialPort::new(COM1_BASE) };
    write_line(
        &mut console,
        format_args!("[FATAL] new-os kernel panic (boot NOT successful): {info}"),
    );
    halt_forever()
}

/// Parks the CPU forever.
///
/// `hlt` stops the core until the next interrupt, which is the correct idle state for a prototype
/// with no scheduler. Interrupts are not enabled by this milestone, so the CPU stays parked.
pub(crate) fn halt_forever() -> ! {
    loop {
        // SAFETY: `hlt` is a privileged instruction that touches no memory and cannot violate a
        // Rust invariant; it only suspends the core. The surrounding infinite loop satisfies the
        // `!` return type.
        unsafe {
            core::arch::asm!("hlt", options(nomem, nostack, preserves_flags));
        }
    }
}
